                <?php if(page_allowed('reports')): ?>
                <section class="page" id="reports">
                    <div class="section-tools actions-only"><button type="button" class="secondary" id="print-report">Print report</button></div>
                    <article class="panel report-builder">
                        <form method="post" class="report-form">
                            <?= csrf_field() ?>
                            <input type="hidden" name="action" value="generate_report">
                            <label>Report type<select name="report_type" id="report-type"><?php foreach(['Sales','Inventory','Low Stock','Expiration','Debts'] as $type): ?><option <?= $reportType===$type?'selected':'' ?>><?= e($type) ?></option><?php endforeach; ?></select></label>
                            <label>Start date<input type="date" name="start_date" value="<?= e($reportStart) ?>"></label>
                            <label>End date<input type="date" name="end_date" value="<?= e($reportEnd) ?>"></label>
                            <label class="report-notes">Notes<input name="notes" placeholder="Optional report note"></label>
                            <button class="primary">Generate report</button>
                        </form>
                    </article>
                    <article class="panel report-output">
                        <div class="panel-head"><div><h2><?= e($reportType) ?> report</h2><p><?= e($reportStart) ?> to <?= e($reportEnd) ?> · <?= count($reportRows) ?> record(s)</p></div></div>
                        <div class="table-wrap"><table><thead><tr><?php foreach($reportColumns as $column): ?><th><?= e($column) ?></th><?php endforeach; ?></tr></thead><tbody><?php if(!$reportRows): ?><tr><td colspan="<?= max(1,count($reportColumns)) ?>" class="empty-row">No records found for this report.</td></tr><?php endif; ?><?php foreach($reportRows as $row): ?><tr><?php foreach($reportColumns as $column): ?><td><?= e($row[$column] ?? '—') ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div>
                        <div class="report-metrics report-totals-footer"><?php foreach($reportMetrics as $metric): ?><div><span><?= e($metric['label']) ?></span><strong><?= e($metric['value']) ?></strong></div><?php endforeach; ?></div>
                    </article>
                    <article class="panel report-history"><div class="panel-head"><div><h2>Generated report history</h2><p>Latest reports created by the owner</p></div></div><div class="table-wrap"><table><thead><tr><th>Type</th><th>Period</th><th>Generated by</th><th>Generated at</th></tr></thead><tbody><?php foreach($reportHistory as $report): ?><tr><td><strong><?= e($report['report_type']) ?></strong></td><td><?= e(($report['start_date'] ?: '—') . ' to ' . ($report['end_date'] ?: '—')) ?></td><td><?= e($report['generated_by'] ?: 'Unknown') ?></td><td><?= e(date('M j, Y g:i A',strtotime($report['generated_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></article>
                </section>
                <?php endif; ?>
